function securityRow(shift,start,end,guards,position,role){return `<div class="security-row"><select class="sec-shift"><option ${shift==='24 Hour'?'selected':''}>24 Hour</option><option ${shift==='Day'?'selected':''}>Day</option><option ${shift==='Night'?'selected':''}>Night</option></select><input class="sec-start" type="datetime-local" value="${start}"><input class="sec-end" type="datetime-local" value="${end}"><select class="sec-guards">${Array.from({length:11},(_,i)=>`<option ${String(i)===guards?'selected':''}>${i}</option>`).join('')}</select><input class="sec-position" value="${position}"><select class="sec-role"><option ${role==='Guard'?'selected':''}>Guard</option><option ${role==='Gaffer'?'selected':''}>Gaffer</option></select><button class="tiny">×</button></div>`}
function restroomLocation(name,id,units,services){return `<section class="location-order-group restroom-group" data-location="${id}"><div class="location-group-head"><div><small>LOCATION</small><input value="${name}"></div><div>${input('Delivery','2026-07-30T07:00','datetime-local')}${input('Pickup','2026-08-04T17:00','datetime-local')}</div></div><div class="restroom-units">${units.map((u,i)=>`<div class="restroom-unit" data-unit="${id}-${i}">${select('Qty',['0','1','2','3','4','5'],u[0])}${select('Unit type',['4-room','2-room','Single','ADA','Luxury trailer','Custom'],u[1])}<label class="unit-label"><input type="checkbox" checked> Unit ${i+1}</label></div>`).join('')}</div><button class="add-row">＋ Add unit type</button><div class="service-schedule"><h5>Service Schedule</h5>${services.map((d,i)=>`<div class="service-row"><input type="datetime-local" value="${d}"><div class="service-units"><span>Service:</span>${units.map((u,j)=>`<label><input type="checkbox" checked data-service-unit="${id}-${j}"> Unit ${j+1}</label>`).join('')}<label><input type="checkbox" class="service-all" checked> All</label></div><button class="tiny">×</button></div>`).join('')}<button class="add-row">＋ Add service</button></div></section>`}
function binLocation(name,id,black,blue,green,roll,delivery,pickup){return `<section class="location-order-group bin-group" data-location="${id}"><div class="location-group-head"><div><small>LOCATION</small><input value="${name}"></div><div>${input('Delivery',delivery,'datetime-local')}${input('Pickup',pickup,'datetime-local')}</div></div><div class="bin-quantities">${[['Black',black],['Blue',blue],['Green',green],['Roll-off',roll]].map(([n,q])=>`<label><span>${n}</span><select data-bin-type="${n}">${Array.from({length:11},(_,i)=>`<option ${i===q?'selected':''}>${i}</option>`).join('')}</select></label>`).join('')}</div><div class="swap-list"><div class="swap-row"><select><option>Swap</option><option>Extra Service</option></select><input type="datetime-local" value="2026-08-03T04:00"><input placeholder="Notes"></div><button class="add-row">＋ Add swap/service</button></div></section>`}
function equipmentLocation(name,id,delivery,pickup,items){return `<section class="location-order-group equipment-group" data-location="${id}"><div class="location-group-head"><div><small>LOCATION</small><div class="location-pills">${['Set','Basecamp','Catering','Crew Parking','Trucks','Other'].map(x=>`<button class="location-pill ${x===name?'active':''}">${x}</button>`).join('')}</div></div><div>${input('Shared delivery',delivery,'datetime-local')}${input('Shared pickup',pickup,'datetime-local')}</div></div><div class="equipment-table"><div class="eq-head"><span>Item</span><span>Qty</span><span>Unit Rate</span><span>Total</span><span></span></div>${items.map(([item,qty,rate])=>`<div class="eq-row"><select class="eq-item"><option>${item}</option><option>Table</option><option>Chair</option><option>Pipe and Drape</option><option>Glowbug</option><option>Handwashing Station</option></select><input class="eq-qty" type="number" min="0" value="${qty}"><input class="eq-rate" type="number" min="0" step="0.01" value="${rate}"><strong class="eq-total">${money(qty*rate)}</strong><button class="tiny">×</button></div>`).join('')}</div><button class="add-row">＋ Add item to ${name}</button></section>`}
function logisticCard(label,name,address,contact,phone,uses){return `<details class="logistic-card"><summary><small>${label}</small><strong>${name}</strong><span>${uses}</span></summary><div class="logistic-info"><div><b>Address</b><span>${address}</span></div><div><b>Contact</b><span>${contact}</span></div><div><b>Phone</b><span>${phone}</span></div></div></details>`}
function preparePrintDetails(){document.querySelectorAll('.vendor-card').forEach(c=>{const v=vendors.find(x=>x.id===c.dataset.cardId);const box=c.querySelector('.print-order-details');if(box){const details=collectOrderDetails(c).split('\n').filter(Boolean).map(x=>`<div>${x.replace(/^•\s*/, '• ')}</div>`).join('');box.innerHTML=`<div class="print-vendor-line"><b>${v?.vendor||''}</b><span>${v?.contact||''}</span><span>${v?.po||''}</span></div><div class="print-order-list">${details}</div>`}})}
function printFullBible(){const previous=new Set(state.expanded);state.expanded=new Set(vendors.map(v=>v.id));render();requestAnimationFrame(()=>{preparePrintDetails();document.body.classList.add('print-full');document.querySelectorAll('.vendor-card').forEach(c=>c.classList.add('print-expanded'));document.querySelectorAll('.logistic-card').forEach(c=>c.setAttribute('open',''));setTimeout(()=>window.print(),120);setTimeout(()=>{document.body.classList.remove('print-full');state.expanded=previous;render()},900)})}
function render(){
 const filtered=vendors.filter(v=>(state.filter==='all'||v.status===state.filter)&&(state.activeCategory==='All'||v.category===state.activeCategory)&&`${v.title} ${v.vendor} ${v.summary}`.toLowerCase().includes(state.query.toLowerCase()));
 const counts=Object.fromEntries(statusFlow.map(x=>[x,vendors.filter(v=>v.status===x).length]));
 document.querySelector('#app').innerHTML=`<header class="topbar"><button class="brand brand-home" id="hubHome"><span class="ts-logo"><svg viewBox="0 0 74 92" aria-hidden="true"><path class="pin-outline" d="M37 3C18 3 5 17 5 36c0 22 17 40 32 53 15-13 32-31 32-53C69 17 56 3 37 3Z"/><path class="mountain" d="M16 39l15-13 8 7 10-10 12 14-12-8-10 10-8-7-15 7Z"/><path class="road" d="M19 69c12-14 24-18 31-27-3 14-12 22-20 31l7 8-9 2-9-14Z"/><path class="star" d="M21 17l2 5 5 2-5 2-2 5-2-5-5-2 5-2 2-5Z"/></svg><span class="ts-wordmark"><b>TAYLOR SCOUT</b><small>PRODUCTION TOOLS</small></span></span></button><div class="top-actions"><span class="cloud-status" id="cloudStatus">${cloudState}</span><button class="dark-action undo-action" id="undoAction" disabled>↶ Undo</button><button class="dark-action" id="openBudgetTop">$ Budget</button><button class="dark-action" id="openWaypointTop">⌖ Waypoint</button><button class="dark-action" id="printBibleTop">⎙ Print Full Bible</button><button class="primary" id="saveBible">Save</button></div></header><div class="app-shell"><aside class="sidebar"><div class="side-show"><span>EL DORADO</span><small>LOCATION BIBLES</small></div><button class="new-bible" id="newBible">＋ New Bible</button><div class="side-label">EPISODES</div><div class="episode-nav">${episodeSidebar()}</div><div class="side-bottom"><button id="openVendorLibrary">▦ Vendor Library</button><button id="openBudgetSide">$ Budget</button><button id="allShows">⌂ All Shows</button></div></aside><main class="main"><section class="hero-card"><div><div class="eyebrow">LOCATION BIBLE</div><h1>${locValue('location_name','Darling Ranch')}</h1><div class="sets">${locValue('set_name','Ext. “Pine Forest” • Ext. “Salt Lake City – Outskirts”')}</div><div class="address">${fullAddress()}</div></div><div class="hero-actions"><button class="ghost" id="editLocation">✎ Edit location</button><button class="primary" id="emailOrdersHero">✉ Email orders</button></div></section><section class="schedule-strip"><div><small>PREP</small><strong>Jul 30–31</strong></div><div><small>FILM</small><strong>Aug 3</strong></div><div><small>WRAP</small><strong>Aug 4</strong></div><div><small>KEY ASSISTANT</small><strong>Taylor Erickson</strong></div><div><small>PRIMARY CONTACT</small><strong>${[locValue('contact_name','Karen Bryden'),locValue('contact_phone','661-510-6366')].filter(Boolean).join(' · ')}</strong></div></section><section class="summary-top"><div><small>LOCATION SUMMARY</small><h3>${locValue('location_name','Darling Ranch')}</h3><span>${locValue('episode_name',locValue('episode_id','Episode 304'))} · ${locValue('set_name','Ext. Pine Forest')}</span></div><div class="top-metrics">${statusFlow.map(st=>`<b class="metric ${st}">${counts[st]||0}<small>${statusLabels[st]}</small></b>`).join('')}</div><div class="summary-actions"><button class="small-btn" id="emailPending">✉ Email pending</button><button class="small-btn" onclick="window.print()">⎙ Print</button><button class="small-btn" id="openBudgetSummary">$ Budget</button></div></section><div class="content-column"><section class="section-card logistics"><div class="section-head"><div><h2>Location Logistics</h2><p>Each operational area has one shared address and contact. Expand a card when multiple places are assigned.</p></div><button class="small-btn" id="editLogistics">✎ Edit</button></div><div class="logistics-grid four">${logisticCard('SET',locValue('location_name','Darling Ranch'),fullAddress(),locValue('contact_name','Karen Bryden'),locValue('contact_phone','661-510-6366'),'Hero Location · Work Trucks · Craft Service')}${logisticCard('BASECAMP',locValue('location_name','Darling Ranch'),fullAddress(),locValue('contact_name','Karen Bryden'),locValue('contact_phone','661-510-6366'),'Basecamp · VIP Parking')}${logisticCard('CREW PARKING','Foxtail Ranch','1165 Foxtail Ranch Rd, Frazier Park, CA 93225','Arne & Deborah Haaland','818-601-2267','Prep/Wrap and film-day crew parking')}${logisticCard('CATERING',locValue('location_name','Darling Ranch'),fullAddress(),locValue('contact_name','Karen Bryden'),locValue('contact_phone','661-510-6366'),'Catering · Meal service')} </div></section><section class="vendor-toolbar"><div><h2>Vendor Orders</h2><p>Each section uses a purpose-built order form.</p></div><button class="primary">＋ Add Vendor Order</button></section><section class="controls"><div class="status-tabs"><button data-filter="all" class="${state.filter==='all'?'active':''}">All <b>${vendors.length}</b></button>${statusFlow.map(st=>`<button data-filter="${st}" class="${state.filter===st?'active':''}">${statusLabels[st]} <b>${counts[st]||0}</b></button>`).join('')}</div><label class="search">⌕<input id="searchInput" placeholder="Search vendors or orders" value="${state.query}"></label></section><div class="category-tabs">${categories.map(c=>`<button data-category="${c}" class="${state.activeCategory===c?'active':''}">${c}</button>`).join('')}</div><div class="vendor-list">${filtered.map(v=>card(v)).join('')}</div></div></main></div>${vendorLibrary()}`;bind();
}
function card(v){const ex=state.expanded.has(v.id);return `<article class="vendor-card ${v.status} ${ex?'expanded':''}" data-card-id="${v.id}"><button class="vendor-summary" data-toggle="${v.id}"><span class="status-rail"></span><span class="vendor-main"><small>${v.category}</small><strong>${v.title}</strong><span>${v.vendor}</span></span><span class="vendor-desc">${v.summary}</span><span class="status-badge ${v.status}">${statusLabels[v.status]}</span><span class="chev">${ex?'⌄':'›'}</span></button>${ex?`<div class="vendor-detail"><div class="card-status-control"><span>ORDER STATUS</span><div class="status-toggle">${statusFlow.map(st=>`<button type="button" data-status="${st}" class="${v.status===st?'active '+st:st}">${statusLabels[st]}</button>`).join('')}</div></div><div class="contact-line"><b>${v.vendor}</b><span>${v.contact}</span></div><div class="print-summary"><strong>${v.title}</strong><span>${v.summary}</span><small>${v.contact} · ${v.po} · ${v.stamp}</small><div class="print-order-details"></div></div><div class="vendor-choice">${select('Vendor',vendorOptionsFor(v).length?vendorOptionsFor(v):[v.vendor],v.vendor)}<button class="small-btn open-library">Browse Vendor Library</button></div>${budgetEditor(v)}${editor(v)}<div class="vendor-footer"><span>${v.stamp}</span><span>${v.po}</span><div><button class="small-btn save-section">Save section</button><button class="small-btn preview-email">Preview email</button></div></div></div>`:''}</article>`}
function bind(){
 const undo=document.querySelector('#undoAction');if(undo)undo.onclick=undoLast;updateUndoButton();
 const printTop=document.querySelector('#printBibleTop');if(printTop)printTop.onclick=printFullBible;
 document.querySelectorAll('[onclick="window.print()"]').forEach(b=>b.onclick=printFullBible);
 const heroEmail=document.querySelector('#emailOrdersHero');if(heroEmail)heroEmail.onclick=()=>openEmailPreview(null);
 const sharedParams=()=>{const current=new URLSearchParams(location.search);const out=new URLSearchParams();['show','showId','showName','locationId','episodeId'].forEach(k=>{const v=current.get(k);if(v)out.set(k,v)});if(!out.get('showName'))out.set('showName','EL DORADO');return out.toString()};
 const openTool=(base)=>{const q=sharedParams();location.href=base+(q?'?'+q:'')};
 const budgetAction=()=>openTool(import.meta.env.VITE_BUDGET_URL||'https://budget.taylorscout.com');
 ['#openBudgetTop','#openBudgetSide','#openBudgetSummary'].forEach(id=>{const el=document.querySelector(id);if(el)el.onclick=budgetAction});
 const waypoint=document.querySelector('#openWaypointTop');if(waypoint)waypoint.onclick=()=>openTool(import.meta.env.VITE_WAYPOINT_URL||'https://waypoint.taylorscout.com');
 const home=document.querySelector('#hubHome');if(home)home.onclick=()=>location.href='https://www.taylorscout.com';
 const allShows=document.querySelector('#allShows');if(allShows)allShows.onclick=()=>location.href='https://www.taylorscout.com';
 const nb=document.querySelector('#newBible');if(nb)nb.onclick=()=>alert('New Bible flow: select episode, scene/set, and Budget location.');
 document.querySelectorAll('.episode-row').forEach(b=>b.onclick=()=>{state.openEpisode=state.openEpisode===b.dataset.episode?'':b.dataset.episode;render()});
 const editLoc=document.querySelector('#editLocation');if(editLoc)editLoc.onclick=openLocationEditor;
 const editLog=document.querySelector('#editLogistics');if(editLog)editLog.onclick=()=>alert('Edit Set, Basecamp, Crew Parking, and Catering logistics.');
 const ov=document.querySelector('#openVendorLibrary');if(ov)ov.onclick=()=>{vendorLibraryOpen=true;render()};
 document.querySelectorAll('.open-library').forEach(b=>b.onclick=()=>{vendorLibraryOpen=true;render()});
 const closeVendorLibrary=()=>{vendorLibraryOpen=false;document.body.style.overflow='';render()};
 const cv=document.querySelector('#closeVendorLibrary');if(cv){cv.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();closeVendorLibrary()})}
 const vendorModal=document.querySelector('#vendorLibraryModal');if(vendorModal){document.body.style.overflow='hidden';vendorModal.addEventListener('click',e=>{if(e.target===vendorModal)closeVendorLibrary()})}
 const escapeVendorLibrary=e=>{if(e.key==='Escape'&&vendorLibraryOpen){document.removeEventListener('keydown',escapeVendorLibrary);closeVendorLibrary()}};document.addEventListener('keydown',escapeVendorLibrary,{once:false});
 document.querySelectorAll('.library-row .small-btn').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();closeVendorLibrary()}));
 const vls=document.querySelector('#vendorLibrarySearch');if(vls)vls.oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.library-row').forEach(r=>r.style.display=r.dataset.libraryText.includes(q)?'grid':'none')};
 document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.toggle;state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);render()});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.activeCategory=b.dataset.category;render()});
 const search=document.querySelector('#searchInput');if(search)search.oninput=e=>{state.query=e.target.value;render();requestAnimationFrame(()=>document.querySelector('#searchInput')?.focus())};
 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=e=>{e.preventDefault();const v=vendors.find(x=>x.id===b.closest('.vendor-card').dataset.cardId);pushUndoSnapshot();v.status=b.dataset.status;render()});
 document.querySelectorAll('.vendor-card input,.vendor-card select,.vendor-card textarea').forEach(el=>{el.addEventListener('input',()=>recalculateCard(el.closest('.vendor-card')));el.addEventListener('change',()=>recalculateCard(el.closest('.vendor-card')))});
 document.querySelectorAll('.vendor-card.expanded').forEach(recalculateCard);
 document.querySelectorAll('.service-all').forEach(x=>x.addEventListener('change',e=>e.target.closest('.service-units').querySelectorAll('input:not(.service-all)').forEach(c=>c.checked=e.target.checked)));
 document.querySelectorAll('.location-pill').forEach(b=>b.onclick=e=>{e.preventDefault();b.parentElement.querySelectorAll('.location-pill').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
 document.querySelectorAll('.save-section').forEach(b=>b.onclick=e=>{e.preventDefault();saveBible(true)});
 document.querySelectorAll('.preview-email').forEach(b=>b.onclick=e=>{e.preventDefault();openEmailPreview(b.closest('.vendor-card'))});
 const save=document.querySelector('#saveBible');if(save)save.onclick=()=>saveBible(false);
 const ep=document.querySelector('#emailPending');if(ep)ep.onclick=()=>openEmailPreview(null);
 document.querySelectorAll('.equipment-search').forEach(inp=>inp.addEventListener('input',()=>filterEquipment(inp)));
 document.querySelectorAll('.quick-equip').forEach(b=>b.onclick=e=>{e.preventDefault();addEquipmentItem(b.closest('.equipment-group'),b.dataset.item)});
 document.querySelectorAll('.add-equipment-item').forEach(b=>b.onclick=e=>{e.preventDefault();const g=b.closest('.equipment-group');const val=g.querySelector('.equipment-search').value.trim();if(val)addEquipmentItem(g,val)});
 document.querySelectorAll('.tiny').forEach(b=>b.onclick=e=>{e.preventDefault();const row=b.closest('.security-row,.service-row,.swap-row,.eq-row');if(row){pushUndoSnapshot();row.remove();recalculateCard(b.closest('.vendor-card'))}});
 document.querySelectorAll('.add-row').forEach(b=>b.onclick=e=>{e.preventDefault();pushUndoSnapshot();duplicateRelevantRow(b)});
 restoreValues();
}
function hoursBetween(a,b){const s=new Date(a),e=new Date(b);return isFinite(s)&&isFinite(e)?Math.max(0,(e-s)/36e5):0}
function recalculateCard(card){if(!card)return;const panel=card.querySelector('[data-budget-card]');if(!panel)return;const id=panel.dataset.budgetCard;let total=0;
 if(id==='security'){card.querySelectorAll('.security-row').forEach(r=>{const h=hoursBetween(r.querySelector('.sec-start').value,r.querySelector('.sec-end').value),g=+r.querySelector('.sec-guards').value,role=r.querySelector('.sec-role').value;const base=role==='Gaffer'?31.5:29.5,ot=role==='Gaffer'?47.25:44.25;const days=Math.max(1,Math.ceil(h/24));let remain=h;for(let i=0;i<days;i++){const dh=Math.min(24,remain);total+=g*(Math.min(8,dh)*base+Math.max(0,dh-8)*ot);remain-=dh}})}
 else if(id==='restrooms'){card.querySelectorAll('.restroom-unit').forEach(u=>{const q=+u.querySelector('select').value,t=u.querySelectorAll('select')[1].value;total+=q*({'4-room':1000,'2-room':700,'Single':250,'ADA':325,'Luxury trailer':2500,'Custom':0}[t]||0)});card.querySelectorAll('.service-row').forEach(r=>{const checked=[...r.querySelectorAll('.service-units input:not(.service-all)')].filter(x=>x.checked).length;total+=checked*175})}
 else if(id==='bins'){card.querySelectorAll('[data-bin-type]').forEach(s=>{const rates={'Black':175,'Blue':175,'Green':175,'Roll-off':650};total+=+s.value*rates[s.dataset.binType]});total+=card.querySelectorAll('.swap-row').length*175}
 else if(id==='equipment'){card.querySelectorAll('.eq-row').forEach(r=>{const q=+r.querySelector('.eq-qty').value||0,rate=+r.querySelector('.eq-rate').value||0,sub=q*rate;total+=sub;const out=r.querySelector('.eq-total');if(out)out.textContent=money(sub)})}
 else if(id==='catering'){const size=card.querySelector('.catering-row select')?.value||'Large',q=+(card.querySelectorAll('.catering-row select')[1]?.value||1);total=q*(size==='Large'?2554:2084)}
 else if(id==='snake'){card.querySelectorAll('.repeat-row').forEach(r=>{const ins=r.querySelectorAll('input');if(ins.length>=3)total+=hoursBetween(`${ins[0].value}T${ins[1].value}`,`${ins[0].value}T${ins[2].value}`)*50.41})}
 else if(id==='maps'){card.querySelectorAll('.map-lines>div').forEach(r=>total+=(+r.querySelector('select').value||0)*90)}
 else if(id==='cleaning'){card.querySelectorAll('.repeat-row').forEach(r=>{const ins=r.querySelectorAll('input');if(ins.length>=3)total+=hoursBetween(`${ins[0].value}T${ins[1].value}`,`${ins[0].value}T${ins[2].value}`)*75})}
 const locked=+panel.dataset.lockedBudget||0,diff=total-locked;panel.querySelector('.working-total').textContent=money(total);panel.querySelector('.variance-total').textContent=money(Math.abs(diff));panel.querySelector('.variance-total').classList.toggle('over',diff>0);panel.querySelector('.variance-note').textContent=diff>0?'Over budget':'Under budget';}
function collectBiblePayload(){const commitments={};document.querySelectorAll('.vendor-card').forEach(card=>{const id=card.dataset.cardId,panel=card.querySelector('[data-budget-card]');commitments[id]={status:vendors.find(v=>v.id===id)?.status||'working',workingTotal:panel?Number((panel.querySelector('.working-total')?.textContent||'0').replace(/[^0-9.-]/g,'')):0,po:card.querySelector('.budget-meta input')?.value||''}});return{version:11,locationId:sharedLocation?.id||locationId||null,location:sharedLocation,updatedAt:new Date().toISOString(),statuses:Object.fromEntries(vendors.map(v=>[v.id,v.status])),values:[...document.querySelectorAll('input,select,textarea')].map((el,i)=>({i,value:el.value,checked:el.checked,type:el.type})),commitments}}
async function saveBible(sectionOnly=false){const data=collectBiblePayload();localStorage.setItem('taylorScoutBibleV7',JSON.stringify(data));cloudPayload=data;const btn=document.querySelector('#saveBible');if(btn)btn.textContent='Saving…';try{if(configured&&showId){const session=await getSession();if(!session)throw new Error('Not signed in');await saveBibleDocument(showId,data);cloudState='Connected · saved'}else cloudState='Saved locally';if(btn)btn.textContent='✓ Saved'}catch(e){console.error('Bible save failed',e);cloudState=`Sync error: ${e.message||'save failed'}`;if(btn)btn.textContent='Save'}updateCloudStatus();setTimeout(()=>{if(btn)btn.textContent='Save'},1200);if(sectionOnly){const n=document.createElement('div');n.className='toast';n.textContent=cloudState.startsWith('Sync error')?cloudState:'Section saved';document.body.append(n);setTimeout(()=>n.remove(),1800)}}
function applyPayload(data){if(!data)return;cloudPayload=data;Object.entries(data.statuses||{}).forEach(([id,st])=>{const v=vendors.find(x=>x.id===id);if(v)v.status=st});const els=[...document.querySelectorAll('input,select,textarea')];(data.values||[]).forEach(x=>{const el=els[x.i];if(!el)return;if(x.type==='checkbox'||x.type==='radio')el.checked=x.checked;else el.value=x.value});document.querySelectorAll('.vendor-card.expanded').forEach(recalculateCard)}
function restoreValues(){try{const data=cloudPayload||JSON.parse(localStorage.getItem('taylorScoutBibleV7')||'null');applyPayload(data)}catch(e){console.warn(e)}}
function updateCloudStatus(){const el=document.querySelector('#cloudStatus');if(el){el.textContent=cloudState;el.classList.toggle('error',cloudState.startsWith('Sync error')||cloudState==='Not signed in')}}
async function refreshSharedData(){if(!configured||!showId){cloudState=configured?'Missing show ID':'Saved locally';updateCloudStatus();return}try{const session=await getSession();if(!session){cloudState='Not signed in';updateCloudStatus();return}const[doc,locations,budget]=await Promise.all([loadBibleDocument(showId),loadLocations(showId),loadBudget(showId)]);sharedBudget=budget?.payload||null;sharedLocation=(locationId?locations.find(x=>x.id===locationId):null)||locations.find(x=>x.is_final)||locations[0]||null;cloudPayload=doc?.payload||cloudPayload;if(cloudPayload)applyPayload(cloudPayload);cloudState='Connected';render();}catch(e){console.error('Bible sync failed',e);cloudState=`Sync error: ${e.message||'connection failed'}`;updateCloudStatus()}}
async function initShared(){await refreshSharedData();realtimeStop();realtimeStop=subscribeBible(showId,()=>refreshSharedData())}

function esc(v=''){return String(v??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]))}
function openLocationEditor(){
 if(!sharedLocation){showToast('No shared location is selected. Open this Bible from a location record first.',true);return}
 const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="location-modal" role="dialog" aria-modal="true" aria-labelledby="editLocationTitle"><div class="modal-head"><div><small>SHARED LOCATION</small><h2 id="editLocationTitle">Edit location</h2></div><button class="modal-close" type="button" aria-label="Close">×</button></div><form id="locationEditForm"><div class="modal-grid"><label><span>Location name</span><input name="location_name" required value="${esc(sharedLocation.location_name)}"></label><label><span>Set name(s)</span><input name="set_name" value="${esc(sharedLocation.set_name)}"></label><label class="wide"><span>Street address</span><input name="address" value="${esc(sharedLocation.address)}"></label><label><span>City</span><input name="city" value="${esc(sharedLocation.city)}"></label><label><span>State</span><input name="state" value="${esc(sharedLocation.state)}"></label><label><span>ZIP</span><input name="postal_code" value="${esc(sharedLocation.postal_code)}"></label><label><span>Area</span><input name="area" value="${esc(sharedLocation.area)}"></label><label><span>Primary contact</span><input name="contact_name" value="${esc(sharedLocation.contact_name)}"></label><label><span>Phone</span><input name="contact_phone" value="${esc(sharedLocation.contact_phone)}"></label><label class="wide"><span>Email</span><input type="email" name="contact_email" value="${esc(sharedLocation.contact_email)}"></label></div><p class="modal-note">Changes update the shared location record used by Location List, Calendar, Budget, Bible, and Scout Route.</p><div class="modal-actions"><button type="button" class="ghost cancel-location">Cancel</button><button type="submit" class="primary save-location">Save shared location</button></div></form></section>`;
 document.body.append(wrap);const close=()=>wrap.remove();wrap.querySelector('.modal-close').onclick=close;wrap.querySelector('.cancel-location').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close()};
 wrap.querySelector('#locationEditForm').onsubmit=async e=>{e.preventDefault();const btn=wrap.querySelector('.save-location');btn.disabled=true;btn.textContent='Saving…';const fd=new FormData(e.currentTarget);const changes=Object.fromEntries([...fd.entries()].map(([k,v])=>[k,String(v).trim()]));try{sharedLocation=await updateLocation(sharedLocation.id,changes);cloudState='Connected · saved';close();render();showToast('Shared location updated');}catch(err){console.error('Location update failed',err);btn.disabled=false;btn.textContent='Save shared location';showToast(err.message||'Could not update location',true)}};
 setTimeout(()=>wrap.querySelector('input')?.focus(),0)
}
function showToast(message,isError=false){const old=document.querySelector('.toast');if(old)old.remove();const n=document.createElement('div');n.className=`toast${isError?' error':''}`;n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),2600)}

function formatEventDate(value){if(!value)return '';const d=new Date(value);if(!isFinite(d))return value;return new Intl.DateTimeFormat('en-US',{weekday:'short',month:'2-digit',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}).format(d).replace(',','').replace(' 0', ' ')}
function collectOrderDetails(card){
 const lines=[];
 card.querySelectorAll('.security-row').forEach(r=>{lines.push(`${r.querySelector('.sec-shift')?.value||'Shift'} Coverage`);lines.push(`Start: ${formatEventDate(r.querySelector('.sec-start')?.value)}`);lines.push(`End: ${formatEventDate(r.querySelector('.sec-end')?.value)}`);lines.push(`${r.querySelector('.sec-guards')?.value||0} ${r.querySelector('.sec-role')?.value||'Guard'}(s) — ${r.querySelector('.sec-position')?.value||'Position TBD'}`);lines.push('')});
 card.querySelectorAll('.location-order-group').forEach(g=>{const name=g.querySelector('.location-group-head input')?.value||g.querySelector('.location-pill.active')?.textContent||g.dataset.location||'Location';lines.push(name.toUpperCase());g.querySelectorAll('.restroom-unit').forEach(u=>{const s=u.querySelectorAll('select');if(+(s[0]?.value||0))lines.push(`• ${s[0]?.value||0} × ${s[1]?.value||'unit'}`)});g.querySelectorAll('[data-bin-type]').forEach(x=>{if(+x.value)lines.push(`• ${x.value} × ${x.dataset.binType} bin(s)`)});g.querySelectorAll('.eq-row').forEach(r=>{const item=r.querySelector('.eq-item')?.value||'',q=r.querySelector('.eq-qty')?.value||0;if(+q)lines.push(`• ${q} × ${item}`)});
 const labels=[...g.querySelectorAll('.location-group-head .field span')].map(x=>x.textContent.trim());const vals=[...g.querySelectorAll('.location-group-head input[type=datetime-local]')];vals.forEach((x,i)=>{if(x.value)lines.push(`${labels[i]||'Schedule'}: ${formatEventDate(x.value)}`)});
 g.querySelectorAll('.swap-row').forEach(r=>{const type=r.querySelector('select')?.value||'Service';const when=r.querySelector('input[type=datetime-local]')?.value;const note=r.querySelector('input[placeholder="Notes"]')?.value;if(when)lines.push(`${type}: ${formatEventDate(when)}${note?' — '+note:''}`)});
 g.querySelectorAll('.service-row').forEach(r=>{const when=r.querySelector('input[type=datetime-local]')?.value;const units=[...r.querySelectorAll('.service-units input:not(.service-all)')].filter(x=>x.checked).map((x,i)=>`Unit ${i+1}`);if(when)lines.push(`Service: ${formatEventDate(when)}${units.length?' — '+units.join(', '):''}`)});lines.push('')});
 if(!lines.length){card.querySelectorAll('input,select,textarea').forEach(el=>{if(el.type==='checkbox'&&!el.checked)return;const v=el.value?.trim();if(v&&v.length<180)lines.push(`• ${v}`)})}
 return lines.join('\n').trim();
}
function openEmailPreview(card){
 const selected=card?[card]:vendors.filter(v=>v.status==='review'||v.status==='approved').map(v=>document.querySelector(`.vendor-card[data-card-id="${v.id}"]`)).filter(Boolean);
 const title=card?(card.querySelector('.vendor-main strong')?.textContent||'Vendor Order'):'Taylor Scout Vendor Orders';
 const sections=selected.map(c=>{const v=vendors.find(x=>x.id===c.dataset.cardId);return `${(v?.title||'ORDER').toUpperCase()} — ${v?.vendor||''}\n${collectOrderDetails(c)}\nPO: ${v?.po||'Pending'}`}).join('\n\n————————————\n\n');
 const greeting=card?`Hi ${((vendors.find(x=>x.id===card.dataset.cardId)?.contact||'').split('·')[0]||'there').trim()},`:'Hello,';
 const text=`${greeting}\n\nPlease confirm the following order for our upcoming work at Darling Ranch for El Dorado, Episode 304.\n\n${sections||'No orders are currently marked Ready for Review or Approved.'}\n\nLOCATION\nDarling Ranch\n1773 Darling Ave\nFrazier Park, CA 93225\n\nPlease confirm availability, pricing, each delivery/service/swap/pickup time, and that the order has been placed as written. Please note any substitutions, additional fees, or schedule conflicts before proceeding.\n\nThank you.`;
 const vendorName=card?(vendors.find(x=>x.id===card.dataset.cardId)?.vendor||'Vendor'):'Vendor Orders';
 const subjectText=`El Dorado_304_Darling Ranch_${vendorName}`;
 const subject=encodeURIComponent(subjectText),body=encodeURIComponent(text);
 const w=window.open('','_blank','width=820,height=760');w.document.write(`<title>Email Preview</title><style>body{font:16px Arial;padding:32px;color:#13283b;background:#f4f7f8}main{max-width:760px;margin:auto;background:#fff;padding:28px;border-radius:14px}textarea{width:100%;height:470px;padding:16px;box-sizing:border-box;line-height:1.45}button,a{display:inline-block;padding:11px 16px;margin:10px 8px 0 0;border-radius:8px;border:1px solid #bfd0d8;background:#fff;color:#13283b;text-decoration:none;font-weight:700}.primary{background:#24a7b8;color:#fff;border-color:#24a7b8}</style><main><h2>${title}</h2><p><b>Subject:</b> ${subjectText}</p><textarea>${text.replace(/</g,'&lt;')}</textarea><br><button onclick="navigator.clipboard.writeText(document.querySelector('textarea').value)">Copy Email</button><a class="primary" href="mailto:?subject=${subject}&body=${body}">Open Mail App</a></main>`)}
function addEquipmentItem(group,item){if(!group)return;const table=group.querySelector('.equipment-table');const row=document.createElement('div');row.className='eq-row';row.innerHTML=`<input class="eq-item" list="equipmentInventory" value="${item}"><select class="eq-qty">${Array.from({length:31},(_,i)=>`<option>${i}</option>`).join('')}</select><input class="eq-rate" type="number" value="0"><strong class="eq-total">$0.00</strong><button class="tiny">×</button>`;table.append(row);row.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>recalculateCard(group.closest('.vendor-card'))));row.querySelector('.tiny').onclick=()=>row.remove()}
function filterEquipment(inp){const q=inp.value.toLowerCase();const list=inp.closest('.equipment-group').querySelector('.equipment-results');list.innerHTML=equipmentInventory.filter(x=>x.toLowerCase().includes(q)).slice(0,12).map(x=>`<button type="button" class="quick-equip" data-item="${x}">${x}</button>`).join('');list.querySelectorAll('button').forEach(b=>b.onclick=e=>{e.preventDefault();addEquipmentItem(inp.closest('.equipment-group'),b.dataset.item)})}
function duplicateRelevantRow(button){const editor=button.closest('.custom-editor');if(!editor)return;let source=editor.querySelector('.security-row:last-child,.service-row:last-child,.swap-row:last-child,.repeat-row:last-child,.map-lines>div:last-child');if(source){const clone=source.cloneNode(true);source.after(clone);clone.querySelectorAll('input,select').forEach(el=>{el.addEventListener('input',()=>recalculateCard(editor.closest('.vendor-card')));el.addEventListener('change',()=>recalculateCard(editor.closest('.vendor-card')))});return}const group=editor.querySelector('.location-order-group:last-of-type');if(group){const clone=group.cloneNode(true);group.after(clone)}}

render();
initShared();
